#!/usr/bin/env node
// Writes docs/INVENTORY.md: every script the site loads (in load order, with what it is, from its own header comment,
// and its size), the pages, the Worker's routes, the generated files and what builds them, and every check (what it
// covers, node or browser). Run it after adding, removing or renaming a file: `node build/inventory.cjs`.
// `node build/inventory.cjs --check` fails when docs/INVENTORY.md is out of step (CI runs it).
const fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..'), rd = (f) => fs.readFileSync(path.join(ROOT, f), 'utf8');
const lines = (f) => rd(f).split('\n').length;
// a file's own description: the first lines of its header comment that say something
function about(f){
  const t = rd(f).split('\n').slice(0, 60).join('\n');
  const m = t.match(/\/\*[\s\S]*?(\*\/|$)/) || t.match(/^(?:\/\/.*\n?)+/m);
  if(!m) return '';
  const said = m[0].replace(/^\/\*+|\*+\/$/g, '').split('\n').map(l => l.replace(/^\s*(\/\/|\*)?\s?/, '').trim())
    .filter(l => l && !/^=+$/.test(l) && !/^@check/.test(l) && !/^Usage:/.test(l));
  return said.slice(0, 2).join(' ').replace(/\s+/g, ' ').replace(/\|/g, '\\|').slice(0, 220);
}
const GENERATED = {
  'js/cm-case-flow-slides.js': 'build/case-flow/slides/dN.json (node build/case-flow/build.cjs)',
  'js/cm-case-flow-scripts.js': 'build/case-flow/scripts/dN.json + days.json (build.cjs)',
  'js/cm-case-flow-sim.js': 'build/case-flow/sim (build.cjs)',
  'js/cm-case-flow-exhibits.js': 'build/case-flow/exhibits (exhibits/assemble.cjs)',
  'js/cm-companion-cases.js': 'build/case-flow/cases (cases/assemble.cjs)',
  'js/cm-deck-slides.js': 'build/videoslide/dayN.json (node build/videoslide/deck-slides.cjs)',
  'curriculum/5-day-flow/*': 'the lesson data (build.cjs)'
};
const out = ['# Code inventory', '', 'Generated by `node build/inventory.cjs` from the files themselves: edit the files, not this page.', ''];
for (const page of ['index.html', 'case-doc.html', 'net-sheet.html']) {
  if (!fs.existsSync(path.join(ROOT, page))) continue;
  const src = rd(page), scripts = [...src.matchAll(/<script src="\/js\/([^"?]+)"/g)].map(m => 'js/' + m[1]);
  out.push(`## ${page} (${lines(page)} lines) loads ${scripts.length} scripts, in this order`, '', '| # | Script | Lines | What it is |', '|---|---|---|---|');
  scripts.forEach((s, i) => out.push(`| ${i + 1} | \`${s}\`${GENERATED[s] ? ' (generated)' : ''} | ${fs.existsSync(path.join(ROOT, s)) ? lines(s) : 'missing'} | ${about(s)} |`));
  out.push('');
}
const loaded = new Set(['index.html', 'case-doc.html', 'net-sheet.html'].filter(p => fs.existsSync(path.join(ROOT, p))).flatMap(p => [...rd(p).matchAll(/\/js\/([^"?]+)"/g)].map(m => 'js/' + m[1])));
const loose = fs.readdirSync(path.join(ROOT, 'js')).filter(f => f.endsWith('.js')).map(f => 'js/' + f).filter(f => !loaded.has(f));
out.push('## Scripts in js/ that no page loads', '', loose.length ? loose.map(f => `- \`${f}\` — ${about(f)}`).join('\n') : 'None.', '');
out.push('## Generated files (never edit by hand)', '', '| File | Built from |', '|---|---|', ...Object.entries(GENERATED).map(([f, s]) => `| \`${f}\` | ${s} |`), '');
const w = rd('worker.js'), routes = [...new Set([...w.matchAll(/path === "(\/[^"]+)"/g)].map(m => m[1]))].sort();
out.push(`## The Worker (worker.js, ${lines('worker.js')} lines): routes`, '', routes.map(r => `\`${r}\``).join(' · '), '');
const dir = '.github/scripts', checks = fs.readdirSync(path.join(ROOT, dir)).filter(f => /\.(c|m)?js$/.test(f)).sort();
const decl = checks.map(f => ({ f, m: rd(`${dir}/${f}`).split('\n').slice(0, 15).join('\n').match(/@check\s+(node|browser(?:-noarg)?)[^—\n]*—\s*(.+)/) }));
for (const kind of ['node', 'browser']) {
  const list = decl.filter(x => x.m && x.m[1].startsWith(kind));
  out.push(`## ${kind === 'node' ? 'Node' : 'Browser'} checks (${list.length})`, '', '| Check | What it covers |', '|---|---|', ...list.map(x => `| \`${x.f}\` | ${x.m[2].trim().replace(/\|/g, '\\|')} |`), '');
}
const helpers = decl.filter(x => !x.m).map(x => x.f);
out.push('## Check helpers (not checks themselves)', '', helpers.map(f => `- \`${dir}/${f}\` — ${about(`${dir}/${f}`)}`).join('\n'), '');
const md = out.join('\n'), file = path.join(ROOT, 'docs/INVENTORY.md');
if (process.argv.includes('--check')) {
  const now = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
  if (now !== md) { console.error('docs/INVENTORY.md is out of step with the files: run node build/inventory.cjs and commit it.'); process.exit(1); }
  console.log('Code inventory in step: docs/INVENTORY.md.');
} else { fs.writeFileSync(file, md); console.log(`wrote docs/INVENTORY.md (${md.split('\n').length} lines)`); }
